// Content is always visible; only a small slide animates in. (Opacity-0
// reveals leave sections blank when they are skipped by a jump or a screenshot.)
const fade = { initial: { y: 18 }, whileInView: { y: 0 }, viewport: { once: true }, transition: { duration: 0.5 } }
const sectionWrap = { position: 'relative', zIndex: 10, padding: 'clamp(64px,9vw,110px) clamp(20px,5vw,60px)' }
