// ── Live examples ───────────────────────────────────────────────────────────
// A real site rendered at desktop width and scaled down to fit its card.
function SitePreview({ id, url }) {
  const box = useRef(null)
  const [scale, setScale] = useState(0.35)
  useEffect(() => {
    const el = box.current
    if (!el) return
    const ro = new ResizeObserver(([e]) => setScale(e.contentRect.width / 1280))
    ro.observe(el)
    return () => ro.disconnect()
  }, [])
  return (
    <div style={{ borderRadius: 14, overflow: 'hidden', border: '1px solid rgba(255,255,255,0.1)', background: '#0d0d14', boxShadow: '0 24px 60px rgba(0,0,0,0.45)' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '9px 12px', background: 'rgba(255,255,255,0.04)', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
        {['#ff5f56', '#ffbd2e', '#27c93f'].map(c => <span key={c} style={{ width: 9, height: 9, borderRadius: 99, background: c }} />)}
        <span style={{ marginLeft: 10, fontSize: 11, color: 'rgba(255,255,255,0.35)', fontFamily: 'monospace' }}>{url}</span>
      </div>
      <div ref={box} style={{ position: 'relative', width: '100%', aspectRatio: '16 / 11', overflow: 'hidden' }}>
        <iframe title={`Example: ${url}`} src={`/examples/${id}.html`} loading="lazy" scrolling="no" tabIndex={-1} sandbox="allow-scripts"
          style={{ position: 'absolute', top: 0, left: 0, width: 1280, height: 880, border: 0, transform: `scale(${scale})`, transformOrigin: '0 0', pointerEvents: 'none' }} />
      </div>
    </div>
  )
}

